#define BAND_SIZE .03
#define ANGLE .2
#define AALIAS 4

float get_col(vec2 uv) {
    float c = cos(ANGLE), s = sin(ANGLE);
    vec2 coord = vec2(uv.x * iResolution.x / iResolution.y, uv.y) / BAND_SIZE;
    coord.y -= iTime;
    coord = vec2(coord.x * c - coord.y * s, coord.x * s + coord.y * c);

    vec3 sample_rgb = texture(iChannel0, uv).xyz;
    float brightness = dot(sample_rgb, vec3(0.2126, 0.7152, 0.0722));
    float max_dist = brightness * .5;

    return abs(fract(coord.y) - .5) < max_dist ? 1. : 0.;
}

float aalias(vec2 fragCoord) {
    float col = 0.;

    for (int x = 0; x < AALIAS; x++)
    for (int y = 0; y < AALIAS; y++) {
        vec2 shift = vec2(float(x) / float(AALIAS), float(y) / float(AALIAS));
        vec2 uv = (fragCoord + shift) / iResolution.xy;

        col += get_col(uv);
    }

    return col / float(AALIAS * AALIAS);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float col = aalias(fragCoord);
    fragColor = vec4(col, col, col, 1.0);
}
